files.StripPanel.ets:
@Component
struct StripPanel {
  build() {
    Column() {
      this.renderStrip()
    }
  }
  @Builder
  renderStrip() {
    List() {
      ForEach(this.tiles, (tile: Tile) => {
        ListItem() { TileView({ tile: tile }) }
      })
    }
    .listDirection(Axis.Horizontal)
    .height(180)
  }
}

files.StripModel.ets:
export class StripModel {
  getTiles(): Tile[] {
    return this.tiles
  }
}

